/// <summary>
/// N.Freidenberger 29.05.24
/// </summary>
public void write()
{
    DirPartyLocationRole        locDirPartyLocationRole;
    DirPartyLocationRole        delDirPartyLocationrole;
    select firstonly locDirPartyLocationRole
        where locDirPartyLocationRole.PartyLocation == this.PartyLocation
        && locDirPartyLocationRole.LocationRole  == this.LocationRole;

    if (locDirPartyLocationRole.RecId)
    {
        this.PartyLocation = 999999999998;
    }
    next Write();

    if (locDirPartyLocationRole.RecId)
    {
        delete_from delDirPartyLocationrole
            where delDirPartyLocationrole.PartyLocation == 999999999998;
    }

}
